M08_INVARIANTS = tuple(InvariantRequirement(*row) for row in _INVARIANT_RECORDS)
M08_INVARIANT_MAP = MappingProxyType({item.number: item for item in M08_INVARIANTS})

def validate_invariant_catalog() -> None:
    numbers = tuple(item.number for item in M08_INVARIANTS)
    if len(M08_INVARIANTS) != 330 or numbers != tuple(range(1, 331)):
        raise MicrobenchmarkIntegrityError("M08 invariant catalog must contain exact unique numbers 1..330")
    if len(M08_INVARIANT_MAP) != 330:
        raise MicrobenchmarkIntegrityError("M08 invariant catalog contains duplicate invariant numbers")
    for attribute in ("proof_id", "proof_target", "assertion_id"):
        values = tuple(getattr(item, attribute) for item in M08_INVARIANTS)
        if len(set(values)) != 330:
            raise MicrobenchmarkIntegrityError(f"M08 invariant {attribute} values must be unique")
    for item in M08_INVARIANTS:
        if not item.frozen_text or not item.semantic_target or not item.proof_target:
            raise MicrobenchmarkIntegrityError("M08 invariant proof records cannot be incomplete")
        actual = hashlib.sha256(item.frozen_text.encode("utf-8")).hexdigest()
        if actual != item.text_digest:
            raise MicrobenchmarkIntegrityError(f"M08 invariant {item.number} frozen text digest drifted")
